      "explanation": "Charles Jolly Jr. killed David Lapine.",
      "revealNarration": "That Saturday, Charles and his cousin John Armstrong drank their way through Potosi — whiskey by the quart, saloons till eight — and walked north to the Lago cabin, drunk. Inside, Charles forced his attentions on Fanny Christopher. David stepped between them. Charles drew his revolver and shot David four times.\n\nThen the two of them killed Fanny, Mary, and the two small children with the cabin's ax, piled straw bedding over the bodies, and set the cabin afire to hide what they had done.\n\nTwelve-year-old Leon Jolly watched it all through a chink in the logs. His testimony convicted them both — the jury took minutes.\n\nOn January 27, 1871, Charles Jolly Jr. and John Armstrong were hanged in the Potosi courthouse yard: the first and only legal hanging in Washington County history.\n\nMotive: drunken assault — David died defending Fanny. Method: revolver, then ax and arson to cover it. Opportunity: Saturday night, an isolated cabin, two drunk cousins no one would turn away."
