        "narration": "Monday morning, November 21, 1870. A neighbor riding past the Lapine cabin, a mile north of Potosi, smells smoke and finds the cabin burned to the ground.\nIn the ruins: the bodies of David Lapine, Fanny Christopher, Mary Christopher, and two small children.\nThe town gathers. Nothing about it looks accidental — but nobody says so yet.\n\nA burned cabin and five dead. The town wants answers, and the sheriff wants names.\nThe question heading into Round 2 is:\nWhere was everyone on Saturday — and who saw David last? 🔒",
